/* ==========================================================================
   BelleVia — Pack ضد القمل · config
   هاد الملف هو الوحيد اللي خاصك تبدّل فيه.

   القاعدة: أي حاجة خاوية هنا = الصفحة كتخبّيها. ما كتخترع والو بلاصتك.
   ========================================================================== */
window.BELLEVIA_CONFIG = {

  /* ── الطلبات ───────────────────────────────────────────────────────────
     الفورم كيسيفط POST بصيغة JSON:
       { productSlug, customerName, phone, city, address, quantity,
         source, eventId, purchaseEventId }
     وكيتسنى { ok: true, orderNumber, total, currency }.

     مسار نسبي عن قصد: الصفحة كتتسيرفا من نفس الـ Pages project اللي فيه
     الـ API، فـ /api/orders كيحل على نفس الدومين.
     ──────────────────────────────────────────────────────────────────── */
  orderApiEndpoint: '/api/orders',

  /** الـ slug ديال المنتج فالكاطالوگ. خاصو يكون هو هو بالضبط. */
  productSlug: 'bellevia-anti-lice',

  /** كيتسيفط ف "المصدر" باش تعرف الطلبات الجايّة من هاد الصفحة. */
  source: 'bellevia-anti-lice',

  /* ── الثمن ─────────────────────────────────────────────────────────────
     ثمن الباك الواحد (سيروم + شامبو). غير الرقم، بلا عملة.

     ⚠️ هاد الرقم كيتبيّن غير للزبون. اللي كيتخلص بصح كيجيبو السيرفر من
        الكاطالوگ (`offerPrice ?? basePrice`)، وعمرو ما كياخد ثمن من
        الصفحة. باش يتطابقو خاص المنتج فالكاطالوگ يكون بـ 29900 سنتيم.
        المجموع فالصفحة = هاد الثمن × الكمية، وهو نفس اللي كيحسب السيرفر
        ما دام ما كاينش سطر ديال هاد المنتج ف PACK_PRICING.
     ──────────────────────────────────────────────────────────────────── */
  price: '299',

  /** ثمن مشطوب (اللي كان). خليه خاوي إلا ما كانش ثمن قديم حقيقي.
      كيبان غير إلا كان أكبر من `price`. ماشي كيدخل فالخلاص ولا فـ JSON-LD:
      اللي كيتخلص بصح هو `price` وحدو، واللي كيتسجل فالكاطالوگ. */
  oldPrice: '350',

  /** الكلمة اللي كتبان حدا الثمن. */
  currency: 'درهم',

  /** كود العملة (ISO 4217) — غير لـ Google/Meta، ماشي للعرض. */
  currencyCode: 'MAD',

  /** أقصى كمية مسموحة فالفورم. الـ API كيرفض أكثر من 10. */
  maxQuantity: 5,

  /* ── التوصيل والخلاص ───────────────────────────────────────────────────
     `delivery` كيتبيّن كيفما كتبتيه. خاوي = السطر ما كيبانش أصلاً.
     التوصيل مجاني هو اللي مفعّل فالنظام (كل طلب كيتسجل بـ freeShipping)،
     وهو نفس اللي كتقول الصفحات الأخرى ديال BelleVia.
     ──────────────────────────────────────────────────────────────────── */
  delivery: 'التوصيل مجاني',

  /** true = الدفع عند الاستلام. حطها false وكيتحيد كل ذكر ليه فالصفحة. */
  cashOnDelivery: true,

  /* ── التواصل ───────────────────────────────────────────────────────────
     عمّر غير اللي عندك. أي حقل خاوي = ما كيبانش، وما كيتحطش رابط ميّت.
     ──────────────────────────────────────────────────────────────────── */

  /** رقم WhatsApp بالصيغة الدولية بلا + ولا مسافات، مثال: '2126XXXXXXXX' */
  whatsapp: '',

  /** رقم الهاتف كيفما كتبغي يبان، مثال: '06XXXXXXXX' */
  phone: '',
};
